167: /**
168:  * Encode raw RGBA pixels (as returned by Tauri's native clipboard readImage)
169:  * to PNG bytes via an offscreen canvas, so a pasted image can be embedded or
170:  * saved like a file-picked one.
171:  */
172: async function rgbaToPng(rgba: Uint8Array, width: number, height: number): Promise<Uint8Array | null> {
173:     const canvas = document.createElement('canvas');
174:     canvas.width = width;
175:     canvas.height = height;
176:     const ctx = canvas.getContext('2d');
177:     if (!ctx) return null;
178:     ctx.putImageData(new ImageData(new Uint8ClampedArray(rgba), width, height), 0, 0);
179:     const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));
180:     if (!blob) return null;
181:     return new Uint8Array(await blob.arrayBuffer());
182: }
