189: async function showServerBlockedDialog(details: string): Promise<void> {
190:     const { message: dialogMessage } = await import('@tauri-apps/plugin-dialog');
191:     const body =
192:         "CalcpadCE's calculation server could not start.\n\n"
193:         + 'The editor still works, but preview, linting, and PDF/Word export '
194:         + 'need the server. Choose Server → Restart Server to try again.\n\n'
195:         + `Details: ${details}`;
196:     try {
197:         await dialogMessage(body, {
198:             title: 'CalcpadCE server unavailable',
199:             kind: 'warning',
200:             okLabel: 'OK',
201:         });
202:     } catch {
203:         // dialog can throw if the runtime is tearing down — the buffered log
204:         // line in the Output panel is the fallback.
205:     }
206: }
