208: async function showConfigInvalidDialog(details: string): Promise<'retry' | 'ignore' | null> {
209:     const { message: dialogMessage } = await import('@tauri-apps/plugin-dialog');
210:     const body =
211:         "CalcpadCE's calculation server could not read its settings file.\n\n"
212:         + `${details}\n\n`
213:         + 'Fix the file, then choose Retry to load it again. Choose Ignore to start '
214:         + 'the server with default settings.';
215:     try {
216:         const choice = await dialogMessage(body, {
217:             title: 'Invalid appsettings.json',
218:             kind: 'error',
219:             buttons: { ok: 'Retry', cancel: 'Ignore' },
220:         });
221:         // Some platforms report the custom label, others the default button name.
222:         return choice === 'Retry' || choice === 'Ok' ? 'retry' : 'ignore';
223:     } catch {
224:         // The Output panel carries the same message.
225:         return null;
226:     }
