240: async function bootstrap(): Promise<void> {
241:     let serverUrl: string;
242:     let isPrimaryWindow = true;
243:     let windowLabel = 'main';
244:     const appVersion = import.meta.env.VITE_APP_VERSION;
245:     let bridge: MessageBridge | null = null;
246:     let tauriBridge: import('./services/tauri-bridge').TauriMessageBridge | null = null;
247:     let serverManager: import('./services/server-manager').TauriServerManager | null = null;
248:     // Server-manager log lines that arrive before the Output panel mounts
249:     // get buffered here, then flushed when appInstance is ready.
250:     const pendingServerLogs: { msg: string; level?: CalcpadLogLevel }[] = [];
251:     // Raw stdout/stderr lines from the Calcpad.Server sidecar (Rust's
252:     // `server-log` event), buffered the same way for the same reason.
253:     const pendingServerRawLogs: { line: string; stream: 'stdout' | 'stderr' }[] = [];
254: 
255:     if (isTauri) {
256:         windowLabel = (await import('@tauri-apps/api/window')).getCurrentWindow().label;
257:         const { invoke } = await import('@tauri-apps/api/core');
258:         const { listen } = await import('@tauri-apps/api/event');
259:         const updatePrimaryWindow = (label: string) => {
260:             isPrimaryWindow = windowLabel === label;
261:             serverManager?.setAutoRestartEnabled(isPrimaryWindow);
262:         };
263:         await listen<string>('primary-window-changed', event => updatePrimaryWindow(event.payload));
264:         updatePrimaryWindow(await invoke<string>('primary_window'));
265:         // Tauri desktop: the Rust layer owns the Calcpad.Server sidecar
266:         // (spawn, kill on exit, port discovery). This manager just tracks
267:         // its URL and surfaces crashes to the Output panel.
268:         const { TauriServerManager } = await import('./services/server-manager');
269:         // Only one window may auto-restart a crashed sidecar — `server-crashed` is
270:         // broadcast, so both would race to respawn it.
271:         serverManager = new TauriServerManager({
272:             appendLine: (msg: string, level?: CalcpadLogLevel) => pendingServerLogs.push({ msg, level }),
273:         }, isPrimaryWindow);
274:         serverManager.onServerLog = (line: string, stream: 'stdout' | 'stderr') => {
275:             pendingServerRawLogs.push({ line, stream });
276:         };
277: 
278:         // The server is shared, so one dialog is enough; the manager already logged the reason.
279:         serverManager.onStartupBlocked = (details: string) => {
280:             if (isPrimaryWindow) void showServerBlockedDialog(details);
281:         };
282:         const manager = serverManager;
283:         serverManager.onConfigInvalid = (details: string) => {
284:             if (isPrimaryWindow) void resolveConfigInvalid(manager, details);
285:         };
286: 
287:         try {
288:             await serverManager.start();
289:         } catch (err) {
290:             if (!serverManager.startFailureReported) {
291:                 const msg = err instanceof Error ? (err.stack ?? err.message) : String(err);
292:                 pendingServerLogs.push({ msg: `[bootstrap] Server failed to start: ${msg}`, level: 'error' });
293:             }
294:             console.error('[bootstrap] Server failed to start:', err);
295:         }
296:         serverUrl = serverManager.getBaseUrl() || '';
297: 
298:         const { TauriMessageBridge } = await import('./services/tauri-bridge');
299:         tauriBridge = new TauriMessageBridge(serverUrl);
300:         tauriBridge.api.setAuthToken(serverManager.getAuthToken());
301:         (window as any).calcpadBridge = tauriBridge;
302:     } else {
303:         // Pure web: use in-process web bridge
304:         serverUrl = getServerUrl();
305:         bridge = new MessageBridge(serverUrl);
306:         (window as any).calcpadBridge = bridge;
307:     }
308: 
309:     const activeBridge = tauriBridge ?? bridge!;
310:     activeBridge.programVersion = appVersion;
311:     // Last session's panes, result mode and open files, stored apart from the settings.
312:     const workspace = await WorkspaceStateStore.load(isTauri);
313: 
314:     // Initialize the platform messaging (reads VITE_PLATFORM='web')
315:     initMessaging();
316: 
317:     // The base message bridge's handleGoToLine looks up the editor via
318:     // window.monaco (matches the vscode-webview convention). Expose it here so
319:     // sidebar tabs (TOC) can post `goToLine` and reach Monaco.
320:     (window as any).monaco = monaco;
321: 
322:     // Auto follows the OS culture on desktop; the webview language is the fallback.
323:     if (isTauri) {
324:         try {
325:             setCurrentCulture((await osLocale()) ?? undefined);
326:         } catch {
327:             // Keep the browser/navigator fallback.
328:         }
329:     }
330: 
331:     // Mount the main app layout
332:     const app = createApp(App, { isDesktop: isTauri });
333:     const i18n = createCalcpadI18n(readLocaleSetting());
334:     app.use(i18n);
335:     if (isTauri) {
336:         const syncMenu = () => {
337:             const { t } = i18n.global as unknown as Composer;
338:             void invoke('set_menu_labels', { labels: menuLabels(t) }).catch(() => {});
339:         };
340:         const localeRef = i18n.global.locale as unknown as Ref<string>;
341:         syncMenu();
342:         watch(localeRef, syncMenu);
343:     }
344:     const appInstance = app.mount('#app') as any;
345: 
346:     // Let the bridge prompt via the in-app quick-pick modal (image storage mode).
347:     activeBridge.setQuickPick(async ({ title, placeholder, options }) => {
348:         const index = await appInstance.showQuickPick({
349:             title,
350:             placeholder,
351:             options: options.map((o: { label: string; detail?: string }) => ({ label: o.label, detail: o.detail })),
352:         });
353:         return index == null ? null : options[index].value;
354:     });
355: 
356:     // Wait for DOM to render, then set up the editor group(s)
357:     await nextTick();
358: 
359:     registerCalcpadLanguage();
360:     registerCalcpadTheme();
361: 
362:     // Apply the persisted app theme before Monaco initializes so the editor
363:     // renders with the right theme first paint. The desktop bridge loads its
364:     // settings asynchronously, so wait for it; the web bridge is synchronous.
365:     if (tauriBridge) await tauriBridge.ready;
366:     setAppTheme(coerceAppTheme(activeBridge.getStoredColorTheme()));
367:     // Before the buffered startup lines are flushed into the Output panel below, so they are
368:     // filtered against the level the user actually chose rather than the default.
369:     setLogLevel(coerceLogLevel((activeBridge as unknown as EditorBridge).getExtraSetting('logLevel')));
370: 
371:     const WORD_WRAP_KEY = 'calcpad.wordWrap';
372:     const initialWordWrap: 'on' | 'off' =
373:         localStorage.getItem(WORD_WRAP_KEY) === 'off' ? 'off' : 'on';
374:     const initialEditorFontFamily = (activeBridge as unknown as EditorBridge).getExtraSetting('editorFontFamily') ?? 'JuliaMono';
375:     let completionDelayMs = Number(activeBridge.getExtraSetting('completionDelayMs') ?? DEFAULT_COMPLETION_DELAY_MS);
376: 
377:     // ---- Editor groups ----
378:     // The desktop supports a single top/bottom split into two editor groups.
379:     // Each group owns a Monaco editor + a TabManager; `activeGroup`/`editor`/
380:     // `tabs` track the focused group and are reassigned on focus change so the
381:     // shared command/save/clipboard closures below always act on it.
382:     const groups = new Map<string, EditorGroup>();
383:     // Per-group wiring applied to every new group after the common wiring
384:     // (populated by the Tauri block: save commands, draft autosave, drop).
385:     const groupWireHooks: ((g: EditorGroup) => void)[] = [];
386:     let activeGroup!: EditorGroup;
387:     let editor!: monaco.editor.IStandaloneCodeEditor;
388:     let tabs!: TabManager;
389:     activeBridge.onRunErrors = errors => {
390:         const model = activeGroup.editor.getModel();
391:         if (model) setRunErrorMarkers(model, errors);
392:     };
393:     const historyCallbacks = { confirm: confirmLeaveUiDoc, restore: restoreNavigation };
394:     let navigationHistory: NavigationHistoryClient | undefined = isTauri
395:         ? undefined : createBrowserNavigationHistory(historyCallbacks);
396: 
397:     function recordNavigation(group: EditorGroup, jump = false): void {
398:         if (group !== activeGroup) return;
399:         const tabId = group.tabs.activeId;
400:         const position = group.editor.getPosition();
401:         const selection = group.editor.getSelection() ?? undefined;
402:         if (tabId && position) {
403:             navigationHistory?.record({ groupId: group.id, tabId, position, selection }, jump);
404:         }
405:     }
406: 
407:     function restoreNavigation(location: NavigationLocation): boolean {
408:         const group = groups.get(location.groupId);
409:         if (!group?.tabs.modelForTab(location.tabId)) return false;
410:         if (activeGroup !== group) setActiveGroup(group);
411:         group.tabs.activate(location.tabId);
412:         if (location.selection) {
413:             group.editor.setSelection(location.selection);
414:             group.editor.revealRangeInCenterIfOutsideViewport(group.editor.getSelection()!);
415:         } else {
416:             const position = group.editor.getModel()!.validatePosition(location.position);
417:             group.editor.setPosition(position);
418:             group.editor.revealPositionInCenterIfOutsideViewport(position);
419:         }
420:         group.editor.focus();
421:         return true;
422:     }
