424:     window.addEventListener('keydown', event => {
425:         const direction = navigationDirection(event, navigator.platform);
426:         if (!direction) return;
427:         event.preventDefault();
428:         event.stopImmediatePropagation();
429:         recordNavigation(activeGroup);
430:         void navigationHistory?.go(direction);
