483:     // ---- Group-scoped refresh helpers ----
484:     function markerToSeverityInfo(severity: monaco.MarkerSeverity) {
485:         switch (severity) {
486:             case monaco.MarkerSeverity.Error:
487:                 return { severityClass: 'lintError', icon: '✕' };
488:             case monaco.MarkerSeverity.Warning:
489:                 return { severityClass: 'warning', icon: '⚠' };
