604:     if (current !== next) {
605:         const max = Math.min(current.length, next.length);
606:         let start = 0;
607:         while (start < max && current[start] === next[start]) start++;
608:         let end = 0;
609:         while (end < max - start && current[current.length - 1 - end] === next[next.length - 1 - end]) end++;
