3131:         /**
3132:          * Route a clipboard / edit action from the native menu to the active
3133:          * group's editor (or a focused sidebar input).
3134:          */
3135:         async function runClipboardAction(
3136:             action: 'cut' | 'copy' | 'paste' | 'select-all' | 'undo' | 'redo' | 'find' | 'replace',
3137:         ): Promise<void> {
3138:             // A real DOM selection (text picked inside the hover panel, parameter hints or
3139:             // output) takes priority over the editor's own model selection, since Monaco
3140:             // renders the main text via its own selection overlay. Copy only, and only when
3141:             // the editor lacks focus: Monaco mirrors its selection into a hidden textarea
3142:             // whose value is a truncated screen-reader representation for large selections,
3143:             // and a cut routed this way also wrote to the clipboard without touching the
3144:             // document.
3145:             if (action === 'copy' && !editor.hasTextFocus()) {
3146:                 const domText = window.getSelection()?.toString() ?? '';
3147:                 if (domText) {
3148:                     try { await tauriClipboard.writeText(domText); } catch { /* ignored */ }
3149:                     return;
3150:                 }
3151:             }
3152:             const editorHasFocus = editor.hasTextFocus();
3153:             if (editorHasFocus) {
3154:                 if (action === 'copy' || action === 'cut') {
3155:                     const sel = editor.getSelection();
3156:                     const model = editor.getModel();
3157:                     if (!sel || !model) return;
3158:                     if (sel.isEmpty()) {
3159:                         // Empty selection: copy/cut the whole current line, matching
3160:                         // Monaco's default. Cut removes the line including its newline.
3161:                         const line = sel.startLineNumber;
3162:                         const text = model.getLineContent(line) + '\n';
3163:                         try { await tauriClipboard.writeText(text); } catch { /* ignored */ }
3164:                         if (action === 'cut') {
3165:                             const lineCount = model.getLineCount();
3166:                             const range = line < lineCount
3167:                                 ? new monaco.Range(line, 1, line + 1, 1)
3168:                                 : new monaco.Range(line, 1, line, model.getLineMaxColumn(line));
3169:                             editor.executeEdits('menu-cut', [{ range, text: '', forceMoveMarkers: true }]);
3170:                         }
3171:                     } else {
3172:                         const text = model.getValueInRange(sel);
3173:                         try { await tauriClipboard.writeText(text); } catch { /* ignored */ }
3174:                         if (action === 'cut') {
3175:                             editor.executeEdits('menu-cut', [{ range: sel, text: '', forceMoveMarkers: true }]);
3176:                         }
3177:                     }
3178:                     return;
3179:                 }
3180:                 if (action === 'paste') {
3181:                     let text = '';
3182:                     try { text = await tauriClipboard.readText(); } catch { /* ignored */ }
3183:                     if (text) {
3184:                         const sel = editor.getSelection();
3185:                         if (!sel) return;
3186:                         editor.executeEdits('menu-paste', [{ range: sel, text, forceMoveMarkers: true }]);
3187:                         editor.pushUndoStop();
3188:                         return;
3189:                     }
3190:                     // No text on the clipboard — try a native image paste.
3191:                     await tryPasteClipboardImage();
3192:                     return;
3193:                 }
3194:                 const cmd = {
3195:                     'select-all': 'editor.action.selectAll',
3196:                     undo: 'undo',
3197:                     redo: 'redo',
3198:                     find: 'actions.find',
3199:                     replace: 'editor.action.startFindReplaceAction',
3200:                 }[action];
3201:                 editor.focus();
3202:                 editor.trigger('menu', cmd, null);
3203:                 return;
3204:             }
3205:             // A focused preview frame (the #UI input form, above all) handles the
3206:             // action against whichever control it is sitting in.
3207:             if (action === 'cut' || action === 'copy' || action === 'paste') {
3208:                 if (appInstance.runFocusedPreviewClipboardAction(action)) return;
3209:             }
3210:             // The menu accelerator beats the preview frame's own Ctrl+F handler, so the
3211:             // frame never sees the key and the host has to open the find bar for it.
3212:             if (action === 'find' && appInstance.openFindInFocusedPreview()) return;
3213:             // Fallback for sidebar / preview / etc.
3214:             const el = document.activeElement as HTMLInputElement | HTMLTextAreaElement | null;
3215:             if (action === 'paste') {
3216:                 let text = '';
3217:                 try { text = await tauriClipboard.readText(); } catch { /* ignored */ }
3218:                 if (!text) return;
3219:                 if (el && 'setRangeText' in el) {
3220:                     const start = el.selectionStart ?? el.value.length;
3221:                     const end = el.selectionEnd ?? start;
3222:                     el.setRangeText(text, start, end, 'end');
3223:                     el.dispatchEvent(new Event('input', { bubbles: true }));
3224:                 }
3225:                 return;
3226:             }
3227:             if (action === 'copy' || action === 'cut') {
3228:                 if (el && 'selectionStart' in el) {
3229:                     const start = el.selectionStart ?? 0;
3230:                     const end = el.selectionEnd ?? start;
3231:                     if (end > start) {
3232:                         const text = el.value.substring(start, end);
3233:                         try { await tauriClipboard.writeText(text); } catch { /* ignored */ }
3234:                         if (action === 'cut') {
3235:                             el.setRangeText('', start, end, 'end');
3236:                             el.dispatchEvent(new Event('input', { bubbles: true }));
3237:                         }
3238:                     }
3239:                 }
3240:                 return;
3241:             }
3242:             if (action === 'select-all') {
3243:                 if (el && 'select' in el && typeof el.select === 'function') el.select();
3244:                 return;
3245:             }
3246:             // undo / redo work via execCommand in inputs.
3247:             if (action === 'undo' || action === 'redo') {
3248:                 document.execCommand(action);
3249:             }
3250:         }
