92: function detectFormatAtCursor(editor: monaco.editor.IStandaloneCodeEditor): CommentFormat {
93:     const model = editor.getModel();
94:     const pos = editor.getPosition();
95:     if (!model || !pos) return 'html';
96: 
97:     let mdActive = false;
98:     for (let i = 1; i <= pos.lineNumber; i++) {
99:         const t = model.getLineContent(i).trim();
100:         if (t === '#md on') mdActive = true;
101:         else if (t === '#md off') mdActive = false;
