function toQuestions(value: unknown): AgentQuestion[] {
    if (!Array.isArray(value)) return [];
    return value
        .filter(q => q && typeof q.question === 'string')
        .map(q => ({
            question: q.question,
            header: typeof q.header === 'string' ? q.header : undefined,
            options: Array.isArray(q.options)
