// ---- In-app confirm dialog ----
export type ConfirmChoice = 'yes' | 'no' | 'cancel'

interface ConfirmState {
  title: string
  message: string
  yesLabel: string
  noLabel: string
  resolve: (c: ConfirmChoice) => void
}

const confirmState = ref<ConfirmState | null>(null)

function showConfirm(opts: {
  title: string
  message: string
  yesLabel?: string
  noLabel?: string
}): Promise<ConfirmChoice> {
  // A prompt still up answers cancel.
  confirmState.value?.resolve('cancel')
  return new Promise(resolve => {
    confirmState.value = {
      title: opts.title,
      message: opts.message,
      yesLabel: opts.yesLabel ?? 'Yes',
      noLabel: opts.noLabel ?? 'No',
      resolve,
    }
  })
}

function resolveConfirm(choice: ConfirmChoice): void {
  const state = confirmState.value
  if (!state) return
  confirmState.value = null
  state.resolve(choice)
}

// ---- External-link prompt ----
interface OpenLinkState {
  url: string
  mode: 'browser' | 'file'
  resolve: (ok: boolean) => void
}

const openLinkState = ref<OpenLinkState | null>(null)

function showOpenLink(url: string, mode: OpenLinkState['mode'] = 'browser'): Promise<boolean> {
  openLinkState.value?.resolve(false)
  return new Promise(resolve => {
    openLinkState.value = { url, mode, resolve }
  })
}

function resolveOpenLink(ok: boolean): void {
  const state = openLinkState.value
  if (!state) return
  openLinkState.value = null
  state.resolve(ok)
}

// ---- External-change conflict prompt ----
interface FileConflictState {
  title: string
  filePath: string
  mine: string
  theirs: string
  resolve: (choice: FileConflictChoice | null) => void
}

const fileConflictState = ref<FileConflictState | null>(null)

/** Resolves null when dismissed without a choice. */
function showFileConflict(opts: Omit<FileConflictState, 'resolve'>): Promise<FileConflictChoice | null> {
  fileConflictState.value?.resolve(null)
  return new Promise(resolve => {
    fileConflictState.value = { ...opts, resolve }
  })
}

