    if (typeof raw.id !== 'string' || !Array.isArray(raw.items)) return null;
    const items = live ? raw.items as ChatItem[] : (raw.items as ChatItem[]).map(item => {
        if (item.kind === 'assistant') return { ...item, streaming: false };
